<?php require __DIR__.'/config.php'; require_auth(); $uid=(int)user()['id']; $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??''; if($action==='add_link'){ $title=trim($_POST['title']??'');$url=trim($_POST['url']??''); if($title!==''&&filter_var($url,FILTER_VALIDATE_URL)){ $plan=$pdo->prepare('SELECT p.max_links FROM users u JOIN plans p ON p.id=u.plan_id WHERE u.id=?');$plan->execute([$uid]);$max=(int)$plan->fetchColumn();$countSt=$pdo->prepare('SELECT COUNT(*) FROM links WHERE user_id=?');$countSt->execute([$uid]); if((int)$countSt->fetchColumn()<$max){$pos=$pdo->prepare('SELECT COALESCE(MAX(position),0)+1 FROM links WHERE user_id=?');$pos->execute([$uid]);$pdo->prepare('INSERT INTO links(user_id,title,url,position) VALUES(?,?,?,?)')->execute([$uid,$title,$url,(int)$pos->fetchColumn()]);}} } elseif($action==='toggle'){ $pdo->prepare('UPDATE links SET is_active=1-is_active WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]); } elseif($action==='delete'){ $pdo->prepare('DELETE FROM links WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]); } elseif($action==='profile'){ $pdo->prepare('UPDATE profiles SET title=?,bio=? WHERE user_id=?')->execute([trim($_POST['title']??''),trim($_POST['bio']??''),$uid]); } header('Location: dashboard.php'); exit; }
$profileSt=$pdo->prepare('SELECT p.*,u.username,pl.name plan_name,pl.max_links FROM profiles p JOIN users u ON u.id=p.user_id LEFT JOIN plans pl ON pl.id=u.plan_id WHERE p.user_id=?');$profileSt->execute([$uid]);$profile=$profileSt->fetch();$linksSt=$pdo->prepare('SELECT * FROM links WHERE user_id=? ORDER BY position,id');$linksSt->execute([$uid]);$links=$linksSt->fetchAll();$clicksSt=$pdo->prepare('SELECT COALESCE(SUM(clicks_count),0) FROM links WHERE user_id=?');$clicksSt->execute([$uid]);$clicks=(int)$clicksSt->fetchColumn();
?><!doctype html><html lang="<?=lang()?>" dir="<?=dir_attr()?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=t('dashboard')?> · <?=APP_NAME?></title><link rel="stylesheet" href="assets/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand">Link<span>iraq</span></div><a class="side-link active" href="dashboard.php"><?=t('dashboard')?></a><a class="side-link" href="#links"><?=t('links')?></a><a class="side-link" href="#analytics"><?=t('analytics')?></a><a class="side-link" href="#appearance"><?=t('appearance')?></a><a class="side-link" href="#billing"><?=t('billing')?></a><?php if(user()['role']==='admin'):?><a class="side-link" href="admin.php"><?=t('admin')?></a><?php endif;?><a class="side-link" href="logout.php"><?=t('logout')?></a></aside><main class="main"><div class="topbar"><div><h1 style="margin:0">مرحباً، <?=e(user()['name'])?></h1><div class="muted">linkiraq.local/u/<?=e($profile['username'])?></div></div><a class="btn btn-primary" target="_blank" href="profile.php?u=<?=urlencode($profile['username'])?>">معاينة الصفحة</a></div><section class="stats" id="analytics"><div class="card stat"><span class="muted">الخطة</span><strong><?=e($profile['plan_name']??'Free')?></strong></div><div class="card stat"><span class="muted">الروابط</span><strong><?=count($links)?> / <?=e((string)$profile['max_links'])?></strong></div><div class="card stat"><span class="muted">النقرات</span><strong><?=number_format($clicks)?></strong></div><div class="card stat"><span class="muted">المشاهدات</span><strong><?=number_format((int)$profile['views_count'])?></strong></div></section><section id="links" class="section" style="padding-bottom:20px"><div class="grid-3" style="grid-template-columns:1.2fr .8fr .8fr"><div class="card"><h2>إضافة رابط</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add_link"><div class="field"><label>عنوان الرابط</label><input name="title" required></div><div class="field"><label>الرابط</label><input type="url" name="url" placeholder="https://" required></div><button class="btn btn-primary">إضافة</button></form></div><div class="card" id="appearance"><h2>الملف الشخصي</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="profile"><div class="field"><label>العنوان</label><input name="title" value="<?=e($profile['title'])?>"></div><div class="field"><label>نبذة</label><textarea name="bio"><?=e($profile['bio'])?></textarea></div><button class="btn">حفظ</button></form></div><div class="card" id="billing"><h2>الاشتراك</h2><p class="muted">الخطة الحالية: <?=e($profile['plan_name']??'Free')?></p><a class="btn btn-dark" href="index.php#pricing">ترقية الخطة</a></div></div></section><section class="card"><h2>روابطي</h2><?php if(!$links):?><p class="muted">لم تضف أي رابط بعد.</p><?php endif;?><?php foreach($links as $link):?><div class="link-item" style="padding:14px 0;border-bottom:1px solid #eef1f6"><div><strong><?=e($link['title'])?></strong><div class="muted" style="font-size:.85rem"><?=e($link['url'])?> · <?=number_format((int)$link['clicks_count'])?> نقرة</div></div><div style="display:flex;gap:8px"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$link['id']?>"><button class="btn"><?=$link['is_active']?'إخفاء':'إظهار'?></button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$link['id']?>"><button class="btn">حذف</button></form></div></div><?php endforeach;?></section></main></div></body></html>